# Code generated by Claude Code with the prompt : "Adapt the mov2gif.sh file to generate videos in MP4 format"

#!/usr/bin/env bash
#
# mov2mp4.sh — Batch convert .mov to web-friendly MP4 (H.264), small and high quality.
#
# One ffmpeg pass: [start title] + video + [end title] → H.264 / yuv420p / faststart.
# Audio is dropped (screen recordings).
#
# Usage:
#   ./mov2mp4.sh [options] <file.mov ...>
#   ./mov2mp4.sh [options] -r <dir>        # all .mov in directory
#
# Options:
#   -w WIDTH   Scale to width px (height auto). Default: original size
#   -f FPS     Frame rate. Default: original (fallback 30)
#   -o DIR     Output directory. Default: same as input
#   -q CRF     H.264 quality, 0–51, lower = better/larger. Default: 23
#   -p PRESET  x264 preset (ultrafast…veryslow). Default: slow
#   -s TEXT    Start frame text. Default: "DEMO START". Use "" to disable.
#   -e TEXT    End frame text. Default: "DEMO END". Use "" to disable.
#   -d DUR     Duration of start/end frames in seconds. Default: 2
#   -x        Dry run — print commands only
#
# Examples:
#   ./mov2mp4.sh recording.mov
#   ./mov2mp4.sh -w 1200 -q 26 *.mov
#   ./mov2mp4.sh -r ~/Movies -o ~/Downloads/mp4s
#   ./mov2mp4.sh -s "DEMO START" -e "DEMO END" recording.mov
#
set -euo pipefail

FFMPEG="/opt/homebrew/opt/ffmpeg-full/bin/ffmpeg"
FFPROBE="/opt/homebrew/opt/ffmpeg-full/bin/ffprobe"
FONT="/System/Library/Fonts/Supplemental/Arial.ttf"

WIDTH=""
FPS=""
OUTDIR=""
CRF=23
PRESET="slow"
START_TEXT="DEMO START"
END_TEXT="DEMO END"
FRAME_DUR=2
DRY_RUN=false
DIR_MODE=""
INPUTS=()

while [[ $# -gt 0 ]]; do
    case "$1" in
        -w) WIDTH="$2"; shift 2 ;;
        -f) FPS="$2"; shift 2 ;;
        -o) OUTDIR="$2"; shift 2 ;;
        -q) CRF="$2"; shift 2 ;;
        -p) PRESET="$2"; shift 2 ;;
        -s) START_TEXT="$2"; shift 2 ;;
        -e) END_TEXT="$2"; shift 2 ;;
        -d) FRAME_DUR="$2"; shift 2 ;;
        -x) DRY_RUN=true; shift ;;
        -r) DIR_MODE="$2"; shift 2 ;;
        -h|--help) sed -n '2,/^$/s/^# \?//p' "$0"; exit 0 ;;
        -*) echo "Unknown: $1" >&2; exit 1 ;;
        *)  INPUTS+=("$1"); shift ;;
    esac
done

if [[ -n "$DIR_MODE" ]]; then
    shopt -s nullglob
    for f in "$DIR_MODE"/*.mov "$DIR_MODE"/*.MOV; do
        INPUTS+=("$f")
    done
    shopt -u nullglob
fi

[[ ${#INPUTS[@]} -eq 0 ]] && { echo "No input files." >&2; exit 1; }

if ! command -v "$FFMPEG" &>/dev/null || ! command -v "$FFPROBE" &>/dev/null; then
    echo "ffmpeg-full not found. Install: brew install ffmpeg-full" >&2
    exit 1
fi

total=${#INPUTS[@]}
i=0
for f in "${INPUTS[@]}"; do
    i=$((i + 1))
    [[ ! -f "$f" ]] && { echo "[$i/$total] $(basename "$f") — not found, skipping" >&2; continue; }

    dir="$(cd "$(dirname "$f")" && pwd)"
    name="$(basename "${f%.*}")"
    out_dir="${OUTDIR:-$dir}"
    [[ -d "$out_dir" ]] || mkdir -p "$out_dir"
    out="${out_dir}/${name}.mp4"

    # Get video dimensions and fps so title frames match the main video
    vid_w="$($FFPROBE -v error -select_streams v:0 -show_entries stream=width -of csv=p=0 "$f" || true)"
    vid_h="$($FFPROBE -v error -select_streams v:0 -show_entries stream=height -of csv=p=0 "$f" || true)"
    [[ -z "$vid_w" || -z "$vid_h" ]] && { vid_w=1920; vid_h=1080; }
    [[ -n "$WIDTH" ]] && { vid_h=$((vid_h * WIDTH / vid_w)); vid_w="$WIDTH"; }
    # H.264 / yuv420p needs even dimensions
    vid_w=$((vid_w / 2 * 2))
    vid_h=$((vid_h / 2 * 2))

    fps="$FPS"
    if [[ -z "$fps" ]]; then
        fps="$($FFPROBE -v error -select_streams v:0 -show_entries stream=avg_frame_rate -of csv=p=0 "$f" || true)"
        [[ -z "$fps" || "$fps" == "0/0" ]] && fps=30
    fi

    # --- build inputs + filter graph: [start] + main + [end] → concat ---
    title_src="color=black:s=${vid_w}x${vid_h}:r=${fps}:d=${FRAME_DUR}"
    dt_opts="fontfile=${FONT}:fontsize=$((vid_h/8)):fontcolor=white:x=(w-text_w)/2:y=(h-text_h)/2"
    norm="setsar=1,format=yuv420p"

    args=(-y -hide_banner -loglevel error)
    filter=""
    labels=""
    n=0

    if [[ -n "$START_TEXT" ]]; then
        echo "  + start frame: \"${START_TEXT}\""
        args+=(-f lavfi -i "$title_src")
        filter+="[$n:v]drawtext=text='${START_TEXT}':${dt_opts},${norm}[v$n];"
        labels+="[v$n]"; n=$((n + 1))
    fi

    args+=(-i "$f")
    filter+="[$n:v]scale=${vid_w}:${vid_h}:flags=lanczos,fps=${fps},${norm}[v$n];"
    labels+="[v$n]"; n=$((n + 1))

    if [[ -n "$END_TEXT" ]]; then
        echo "  + end frame: \"${END_TEXT}\""
        args+=(-f lavfi -i "$title_src")
        filter+="[$n:v]drawtext=text='${END_TEXT}':${dt_opts},${norm}[v$n];"
        labels+="[v$n]"; n=$((n + 1))
    fi

    filter+="${labels}concat=n=${n}:v=1:a=0[out]"

    args+=(-filter_complex "$filter" -map "[out]" -an
           -c:v libx264 -preset "$PRESET" -crf "$CRF" -pix_fmt yuv420p
           -movflags +faststart "$out")

    echo "[$i/$total] $(basename "$f") → $(basename "$out")"
    if $DRY_RUN; then
        printf '  %q' "$FFMPEG" "${args[@]}"; echo
    else
        "$FFMPEG" "${args[@]}"
    fi
done

echo "done."
